window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-42901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόβος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 695 na letra φ · nº geral 42901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de expulsar, de amedrontar 2 objeto que assusta; espantalho 3 fuga: φόβου ἄρχεσθαι hom. começar a fugir 4 medo; pavor; terror de algo, gen., causado por, ἀπό, παρά, πρός ou ἐκ e gen., em rel. a alguém ou algo, περί e ac. ou dat. ou gen.: φόβον ποιεῖν ou τεύχειν hom. provocar medo, φόβον παρέχειν eur. ou παρασκευάζειν xen. causar medo, φόβον ἐπιβάλλειν hom., ou ἐμβάλλειν ou ἐπιτιθέναι ou ἐντιθέναι xen. ou προσάγειν plat. lançar o medo no espírito de alguém, εἰς φόβον καταστῆναι tuc. ficar com medo, φόβος ἐστί ou φόβος deve-se temer, ὑπὸ τοῦ φόβου προαποθνῄσκειν xen. morrer antecipadamente de medo, πρὸς τὸν πρῶτον φόβον tuc. ao primeiro sinal de medo, ἐν φόβῳ εἶναι plat. estar com medo, εἰς φόβον ἔρχεσθαι plat. ficar com medo, φόβον ἔχειν her. ter medo, φόβον λαμβάνειν xen. ficar com medo, φόβους δεδοικέναι eur. sentir medo, φόβον e φόβους φοβεῖσθαι plat. estar com medo, φόβῳ ésql. ou φόβοις sóf. ou ἐκ φόβου sóf. ou διὰ φόβου eur. ou διὰ φόβον xen. ou διὰ τὸν φόβον plat. por medo ♦ pl. οἱ φόβοι 5 objetos que provocam medo 6 fantasma; espectro 7 ação de pôr em fuga ♦ Φόβος 8 Fobos; Pavor, divindade.</p></section></article>\n<article id=\"entry-dgp-42902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιβάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 696 na letra φ · nº geral 42902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sacerdotisa de Febo 2 sacerdotisa inspirada; profetisa. 〈Φοῖβος〉</p></section></article>\n<article id=\"entry-dgp-42903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιβαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 697 na letra φ · nº geral 42903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inspirado pelo deus 2 que fala de modo profético; oracular. 〈φοῖβος〉</p></section></article>\n<article id=\"entry-dgp-42904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φοίβειος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 698 na letra φ · nº geral 42904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον de Febo. 〈Φοῖβος〉</p></section></article>\n<article id=\"entry-dgp-42905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φοίβη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 699 na letra φ · nº geral 42905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φοῖβος.</p></section></article>\n<article id=\"entry-dgp-42906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φοιβήϊος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 700 na letra φ · nº geral 42906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Φοίβειος.</p></section></article>\n<article id=\"entry-dgp-42907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιβόλαμπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 701 na letra φ · nº geral 42907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = φοιβόληπτος.</p></section></article>\n<article id=\"entry-dgp-42908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιβόληπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 702 na letra φ · nº geral 42908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">possuído, inspirado por Febo. 〈Φοῖ­βος, ληπτός〉</p></section></article>\n<article id=\"entry-dgp-42909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιβονομέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 703 na letra φ · nº geral 42909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">viver sob as leis de Febo; ser puro. 〈Φοῖβος, νόμος〉</p></section></article>\n<article id=\"entry-dgp-42910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοῖβος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 704 na letra φ · nº geral 42910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 claro; brilhante, luminoso; puro ♦ ὁ Φοῖ­βος 2 Febo, o brilhante, denominação de Apolo ♦ ἡ Φοί­βη 3 Febe, n. de deusa e de m.</p></section></article>\n<article id=\"entry-dgp-42911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 705 na letra φ · nº geral 42911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da cor de sangue; de um vermelho escuro. 〈φοινός〉</p></section></article>\n<article id=\"entry-dgp-42912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινίκειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 706 na letra φ · nº geral 42912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φοινικήϊος.</p></section></article>\n<article id=\"entry-dgp-42913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικέος-οῦς, έα-ῆ, έον-οῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 707 na letra φ · nº geral 42913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vermelho; escarlate; purpúreo. 〈φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φοινίκη, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 708 na letra φ · nº geral 42914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ἡ) 1 Fenícia, região da Ásia ou região de Cartago 2 Astron. constelação da Ursa Menor. 〈Φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικήϊος1, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 709 na letra φ · nº geral 42915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. 1 produzido de folhas de palmeira (vinho, roupa) 2 〈φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικήϊος2, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 710 na letra φ · nº geral 42916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. da Fenícia; fenício (alfabeto). 〈Φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φοινικικός1, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 711 na letra φ · nº geral 42917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cor vermelha purpúrea. 〈Φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φοινικικός2, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 712 na letra φ · nº geral 42918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fenício 2 cartaginês; púnico. 〈Φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινίκινος1, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 713 na letra φ · nº geral 42919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de palmeira (vinho, unguento) 2 feito da madeira da palmeira ♦ ἡ φοινικίνη 3 Medic. espécie de emplastro. 〈φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινίκινος2, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 714 na letra φ · nº geral 42920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fenício: ἡ φοινικίνη νόσος gal. mal fenício, elefantíase. 〈φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινίκιος1, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 715 na letra φ · nº geral 42921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vermelho púrpura; purpúreo. 〈φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φοινίκιος2, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 716 na letra φ · nº geral 42922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Fenícia; fenício. 〈Φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 717 na letra φ · nº geral 42923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tecido de cor vermelha escarlate 2 cobertura vermelha de cavalo. 3 roupa vermelha; manto vermelho de guerra 4 cortina vermelha ou tapete vermelho escarlate 5 estandarte vermelho escarlate usado em cerimônia de imprecação 6 bandeira escarlate para os sinais da marinha 7 cartaz com letras vermelhas 8 palmeira ornamental. 〈φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 718 na letra φ · nº geral 42924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tintureiro que faz uso de púrpura ou vermelho 2 alto dignatário, aquele que veste púrpura, entre os persas. 〈φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικοβάλανος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 719 na letra φ · nº geral 42925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fruto da palmeira; tâmara. 〈φοῖνιξ, βάλανος〉</p></section></article>\n<article id=\"entry-dgp-42926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 720 na letra φ · nº geral 42926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φοινίκεος.</p></section></article>\n<article id=\"entry-dgp-42927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικοπάρῃος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 721 na letra φ · nº geral 42927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de flancos escarlates (navio).</p></section></article>\n<article id=\"entry-dgp-42928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικοῦς, ῆ, οῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 722 na letra φ · nº geral 42928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φοινίκεος.</p></section></article>\n<article id=\"entry-dgp-42929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινικών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 723 na letra φ · nº geral 42929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bosque de palmeiras. 〈φοῖνιξ〉</p></section></article>\n<article id=\"entry-dgp-42930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοῖνιξ1, ικος (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 724 na letra φ · nº geral 42930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 púrpura; tintura de púrpura 2 palmeira: ὁ φ. palmeira macho ou fêmea, ἡ φ. palmeira fêmea 3 folha ou ramo da palmeira 4 fruto da palmeira; tâmara: οἶνος φοινίκων xen. vinho de tâmaras 5 pó preparado com a flor de palmeira; perfume de palma 6 espécie de cítara, feita da madeira de palmeira 7 fênix, pássaro fabuloso do Egito 8 espécie de planta gramínea.</p></section></article>\n<article id=\"entry-dgp-42931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοῖνιξ2, ικος</h1><div class=\"entry-meta\"><span>DGP · ordem 725 na letra φ · nº geral 42931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de cor vermelho púrpura ou escarlate.</p></section></article>\n<article id=\"entry-dgp-42932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φοῖνιξ3, ικος</h1><div class=\"entry-meta\"><span>DGP · ordem 726 na letra φ · nº geral 42932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 fenício 2 cartaginês ♦ ὁ Φοῖνιξ 3 Fênix, n. de h., de cidade, de monte, de fonte e de rio.</p></section></article>\n<article id=\"entry-dgp-42933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοίνιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 727 na letra φ · nº geral 42933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., ος, ον 1 de cor vermelha cor de sangue; purpúreo 2 coberto de sangue; ensanguentado; sangrento 3 que derrama sangue; sanguinário; assassino. 〈φοινός〉</p></section></article>\n<article id=\"entry-dgp-42934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοίνισσα, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 728 na letra φ · nº geral 42934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de φοῖνιξ2 e 3.</p></section></article>\n<article id=\"entry-dgp-42935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινίσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 729 na letra φ · nº geral 42935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. pas. ἐφοινίχθην) 1 avermelhar com sangue 2 fazer corar de vergonha ou de pudor, ac. 3 intr. ficar vermelho; avermelhar ♦ méd. pas. 4 tornar-se vermelho; corar. 〈φοινός〉</p></section></article>\n<article id=\"entry-dgp-42936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 730 na letra φ · nº geral 42936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vermelho (de sangue) 2 assassino; sanguinário 3 letal; mortal ♦ τὸ φοινόν 4 ruína; destruição.</p></section></article>\n<article id=\"entry-dgp-42937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιταλέος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 731 na letra φ · nº geral 42937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., ος, ον 1 que faz vagar; que faz enlouquecer 2 errante; louco. 〈φοιτάω〉</p></section></article>\n<article id=\"entry-dgp-42938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιτάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 732 na letra φ · nº geral 42938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem., n.) 1 que vai para lá e para cá; que vagueia: φ. ἐμπορίη a.p. comércio de importação e exportação 2 louco; errante: φ. νόσος sóf. loucura. 〈φοιτάω〉</p></section></article>\n<article id=\"entry-dgp-42939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 733 na letra φ · nº geral 42939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φοιτήσω) 1 ir e vir sem cessar; caminhar; vagar; errar: φ. διὰ νῆος hom. ir e vir em um barco 2 (marido e mulher) frequentar para manter relações sexuais com, πρός ou παρά e ac., ou dat. 3 ir habitualmente; visitar alguém com frequência 4 ter relações amistosas com alguém; frequentar: φ. ἐπὶ τὰς θύρας her. ou ἐπὶ τὰς θύρας plut. vir freqüentemente bater à porta de alguém, φ. ἐς ἀγορὴν, ἐς ἄγρας her. ir assiduamente ao mercado, à caça, φ. ἐς τὰ χρηστήρια her. ir com frequência consultar o oráculo, φ. εἰς τὰ διδασκαλεῖα xen. ir à escola 5 ir à escola; ser estudante 6 (coisa) ir e vir regularmente, periodicamente 7 (doença) recidivar; voltar 8 (notícia, fama) difundir-se.</p></section></article>\n<article id=\"entry-dgp-42940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοίτησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 734 na letra φ · nº geral 42940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de ir e vir; de ir com frequência, de frequentar 2 ida à escola. 〈φοιτάω〉</p></section></article>\n<article id=\"entry-dgp-42941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοιτητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 735 na letra φ · nº geral 42941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aluno; discípulo. 〈φοιτάω〉</p></section></article>\n<article id=\"entry-dgp-42942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοῖτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 736 na letra φ · nº geral 42942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de ir e vir, de vagar; agitação incessante 2 extravio do espírito; loucura.</p></section></article>\n<article id=\"entry-dgp-42943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φολιδωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 737 na letra φ · nº geral 42943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coberto de escamas 2 disposto em forma de escamas; imbricado. 〈φολίς〉</p></section></article>\n<article id=\"entry-dgp-42944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φολίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 738 na letra φ · nº geral 42944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escama de réptil 2 escama de metal 3 mancha na pele; pinta; estria 4 lambril.</p></section></article>\n<article id=\"entry-dgp-42945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φολκός, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 739 na letra φ · nº geral 42945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) vesgo ou cambaio, epít. de Tersites.</p></section></article>\n<article id=\"entry-dgp-42946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φονάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 740 na letra φ · nº geral 42946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) ser ávido de carnificina ou de homicídio; ser sanguinário. 〈φονή〉</p></section></article>\n<article id=\"entry-dgp-42947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φονεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 741 na letra φ · nº geral 42947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) homicida; criminoso; assassino.</p></section></article>\n<article id=\"entry-dgp-42948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φονεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 742 na letra φ · nº geral 42948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 matar 2 cortar para matar (pescoço). 〈φονεύς〉</p></section></article>\n<article id=\"entry-dgp-42949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φονή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 743 na letra φ · nº geral 42949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. 1 morticínio; massacre: σπᾶν φοναῖς ἀλ­λήλους sóf. dilacerar-se mútua e mortalmente 2 matança: φοναὶ θηροκτόνοι eur. matança de animais selvagens, caça 3 morte; sangue derramdo. 〈πεφνεῖν〉</p></section></article>\n<article id=\"entry-dgp-42950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φονικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 744 na letra φ · nº geral 42950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de homicídio: φονικοὶ νόμοι dem. leis sobre o homicídio 2 inclinado a matar; sanguinário ♦ τὸ φονικόν 3 natureza sanguinária 4 pl. atos homicidas. 〈φόνος〉</p></section></article>\n<article id=\"entry-dgp-42951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόνιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 745 na letra φ · nº geral 42951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 de sangue (ferida) 2 que faz correr sangue; assassino; sanguinário; letal; mortal 3 manchado de sangue; ensanguentado. 〈φόνος〉</p></section></article>\n<article id=\"entry-dgp-42952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φονολιβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 746 na letra φ · nº geral 42952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que goteja sangue resultante de assassínio (trono). 〈φόνος, λείβω〉</p></section></article>\n<article id=\"entry-dgp-42953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φονόρρυτος,</h1><div class=\"entry-meta\"><span>DGP · ordem 747 na letra φ · nº geral 42953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. φονόρυτος, ος, ον inundado, encharcado de sangue. 〈φόνος, ῥέω〉</p></section></article>\n<article id=\"entry-dgp-42954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 748 na letra φ · nº geral 42954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assassínio; morte: φόνον φέρειν ou τεύ­χειν τινί hom. causar, perpetrar a morte de alguém, φόνον βουλεύειν τινί tramar a morte de alguém 2 Jur. homicídio: φόνου διώκειν, παραδιδόναι, δικάζειν perseguir, entregar, julgar um homem acusado de assassínio 3 massacre; carnificina 4 pena de morte 5 sangue derramado por um crime; sangue de uma vítima 6 vítima de crime; cadáver de homem morto 7 instrumento de crime 8 causa de um homicídio. 〈πέφνειν〉</p></section></article>\n<article id=\"entry-dgp-42955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοξός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 749 na letra φ · nº geral 42955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">agudo; pontudo.</p></section></article>\n<article id=\"entry-dgp-42956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 750 na letra φ · nº geral 42956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vento favorável 2 ação de trazer; aporte (de taxa, de voto) 3 pagamento: φορὰν φέρειν tuc. pagar um imposto, φορὰν λείπειν xen. cessar de pagar 4 ação de levar (para sepultar) 5 ação de caminhar, de mover-se: φ. ἄστρων plat. curso dos astros, φ. οὐρανοῦ plat. movimento do céu 6 pendor; inclinação para; dedicação a algo, πρός ou ἐπί e ac.: φ. πρὸς τὸν νεωτερισμόν plut. inclinação para as inovações 7 fardo; carga: κατὰ φοράν hipócr. de uma só vez 8 produção de, gen.: φ. καρπῶν teofr. produção de frutos 9 fertilidade; fecundidade 10 produção abundante; provisão: φ. προδότων καὶ δωροδόκων dem. profusão de traidores e de corruptos 11 seita; escola de filosofia. 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-42957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοράδην</h1><div class=\"entry-meta\"><span>DGP · ordem 751 na letra φ · nº geral 42957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 sendo carregado, sendo transportando em cadeira, em liteira 2 rapidamente. 〈φορά, -δην〉</p></section></article>\n<article id=\"entry-dgp-42958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορβαδικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 752 na letra φ · nº geral 42958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de rebanhos. 〈φορβή〉</p></section></article>\n<article id=\"entry-dgp-42959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορβάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 753 na letra φ · nº geral 42959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que fornece alimento ou pasto; fecundo; nutritivo 2 que vai ao pasto; que pasta (animal) ♦ ἡ φορβάς 3 égua que pasta. 〈φέρβω〉</p></section></article>\n<article id=\"entry-dgp-42960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορβειά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 754 na letra φ · nº geral 42960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cabresto para amarrar o cavalo à mangedoura 2 pedaço de couro que os tocadores de flauta fixam em torno dos lábios para suavizar o som. 〈φορβή〉</p></section></article>\n<article id=\"entry-dgp-42961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορβή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 755 na letra φ · nº geral 42961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pasto; forragem; alimentação (dos animais). 〈φέρβω〉</p></section></article>\n<article id=\"entry-dgp-42962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορέεσκον</h1><div class=\"entry-meta\"><span>DGP · ordem 756 na letra φ · nº geral 42962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter., φορέῃσι 3ª sing. subj. pres., de φορέω.</p></section></article>\n<article id=\"entry-dgp-42963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 757 na letra φ · nº geral 42963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cadeira com carregador; liteira 2 animal de carga 3 remuneração do carregador. 〈φορεύς〉</p></section></article>\n<article id=\"entry-dgp-42964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 758 na letra φ · nº geral 42964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 carregador 2 carregador de liteira ♦ adj. 3 de carga (cavalo). 〈φορέω〉</p></section></article>\n<article id=\"entry-dgp-42965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 759 na letra φ · nº geral 42965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐφόρουν, fut. φορήσω, aor. ἐφόρηκα, perf. πεφόρηκα; pas. aor. ἐφορήθην, perf. πεφόρημαι) 1 levar aqui e ali: μ᾽ αἰεὶ κῦμα ἐφόρεε hom. continuamente as ondas me levavam para lá e para cá, καί οἱ τὰς ἀγγελίας ἐφόρεε οὗτος her. esse lhe levava as notícias 2 carregar habitualmente; levar habitualmente sobre si; ter (vestimentas, armas, adorno): φ. κεφαλὰς ἰσχυράς her. ter crâneos fortes, φ. ἕν ἦθος μόνον sóf. ter uma única convicção 3 suportar; tolerar (vinho puro, calor) ♦ méd. 4 levar para si ou com as próprias mãos, ac. ♦ pas. 5 ser arrastado, sacudido; ser levado embora. 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-42966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορηδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 760 na letra φ · nº geral 42966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = φοράδην.</p></section></article>\n<article id=\"entry-dgp-42967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόρημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 761 na letra φ · nº geral 42967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fardo; carga 2 roupas; acessórios; adornos 3 liteira 4 col. carregadores. 〈φορέω〉</p></section></article>\n<article id=\"entry-dgp-42968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορήμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 762 na letra φ · nº geral 42968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e φορῆναι inf. pres. ép. de φορέω.</p></section></article>\n<article id=\"entry-dgp-42969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορητός, ή</h1><div class=\"entry-meta\"><span>DGP · ordem 763 na letra φ · nº geral 42969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., ός, όν 1 levado; transportado 2 que se move; que vagueia 3 instável; volúvel (caráter) 4 suportável; tolerável. 〈φορέω〉</p></section></article>\n<article id=\"entry-dgp-42970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορίνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 764 na letra φ · nº geral 42970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele espessa e dura; couro (como de rinoceronte ou de camelo) 2 vestimenta de pele espessa, de couro.</p></section></article>\n<article id=\"entry-dgp-42971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φορκίδες, ων (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 765 na letra φ · nº geral 42971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filhas de Fórcis, as três Graias. 〈Φόρκυς〉</p></section></article>\n<article id=\"entry-dgp-42972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φόρκυνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 766 na letra φ · nº geral 42972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Forcino, porto.</p></section></article>\n<article id=\"entry-dgp-42973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φόρκυς, υος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 767 na letra φ · nº geral 42973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Fórcis, pai das Graias.</p></section></article>\n<article id=\"entry-dgp-42974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορμηδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 768 na letra φ · nº geral 42974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em forma de trança; por entrecruzamento, i.e., alternativamente, em comprimento e largura. 〈φορμός, δην〉</p></section></article>\n<article id=\"entry-dgp-42975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόρμιγξ, ιγγος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 769 na letra φ · nº geral 42975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lira ou pequena harpa primitiva, de três, quatro, e, mais tarde, sete cordas.</p></section></article>\n<article id=\"entry-dgp-42976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορμίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 770 na letra φ · nº geral 42976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) tocar lira. 〈φόρμιγξ〉</p></section></article>\n<article id=\"entry-dgp-42977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορμικτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 771 na letra φ · nº geral 42977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tocador de lira, epít. de Apolo, Orfeu, Aríon. 〈φόρμιγξ〉</p></section></article>\n<article id=\"entry-dgp-42978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορμίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 772 na letra φ · nº geral 42978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequeno cesto, usado para pesca. 〈φορμός〉</p></section></article>\n<article id=\"entry-dgp-42979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φορμίων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 773 na letra φ · nº geral 42979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Formião, n. de h.</p></section></article>\n<article id=\"entry-dgp-42980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 774 na letra φ · nº geral 42980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cesto feito de junco ou de esparto 2 trança; tapete; coberta 3 capote (de marinheiro) 4 balaio, medida para cereais. 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-42981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 775 na letra φ · nº geral 42981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cobrar uma taxa ou impostos sobre, ac. 2 pagar impostos, tributos. 〈φορολόγος〉</p></section></article>\n<article id=\"entry-dgp-42982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορολόγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 776 na letra φ · nº geral 42982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cobrador de impostos. 〈φόρος, λέγω〉</p></section></article>\n<article id=\"entry-dgp-42983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόρος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 777 na letra φ · nº geral 42983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ὁ) 1 taxa; tributo; imposto: φόρον ὑποτε­λέειν her. quitar um imposto, φόρον φέρειν ar. trazer contribuições, φόρον τάξασθαι her. aceitar um imposto 2 pagamento. 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-42984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορός, ός,</h1><div class=\"entry-meta\"><span>DGP · ordem 778 na letra φ · nº geral 42984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">όν 1 que leva para frente; que impulsiona 2 propício; favorável (vento) 3 que leva para; que dispõe a, πρός e ac. 4 produtivo; fecundo 5 fem. fértil; grávida (mulher). 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-42985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτηγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 779 na letra φ · nº geral 42985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (animal de carga) carregar fardos 2 transportar (em nau). 〈φορτηγός〉</p></section></article>\n<article id=\"entry-dgp-42986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτηγικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 780 na letra φ · nº geral 42986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para o transporte de mercadorias: φορτηγικὴ ναῦς ou φορτηγικὸν πλοῖον barco mercante. 〈φόρτος, ἄγω〉</p></section></article>\n<article id=\"entry-dgp-42987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτηγός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 781 na letra φ · nº geral 42987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que transporta mercadorias: φορτηγὸς ναῦς ou φορτηγὸν πλοῖον barco mercante. 〈φόρτος, ἄγω〉</p></section></article>\n<article id=\"entry-dgp-42988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 782 na letra φ · nº geral 42988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φορτίσω, át. φορτιῶ, perf. pas. πεφόρτισμαι) 1 carregar um fardo, ac. ♦ méd. 2 carregar para o navio; embarcar uma carga. 〈φόρτος〉</p></section></article>\n<article id=\"entry-dgp-42989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 783 na letra φ · nº geral 42989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de tem carga pesada (navio) 2 fatigante; cansativo para alguém, dat. 3 insuportável; inoportuno: φορτικὰ λέγειν plat. dizer coisas inoportunas 4 grosseiro; vulgar; rude (prazer, arte) ♦ τὸ φορτικόν 5 orgulho grosseiro 6 vulgaridade (do estilo). 〈φόρτος〉</p></section></article>\n<article id=\"entry-dgp-42990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτικότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 784 na letra φ · nº geral 42990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grosseria; insolência. 〈φορτικός〉</p></section></article>\n<article id=\"entry-dgp-42991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 785 na letra φ · nº geral 42991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 grosseiramente; de uma maneira vulgar 2 em desordem; sem arte 3 em termos inconvenientes; grosseiramente.</p></section></article>\n<article id=\"entry-dgp-42992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 786 na letra φ · nº geral 42992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 carga; fardo 2 mercadorias transportadas por mar; carga de navio 3 peso; fardo, ref. a pessoa. 〈φόρτος〉</p></section></article>\n<article id=\"entry-dgp-42993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 787 na letra φ · nº geral 42993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">navio mercante; navio de carga. 〈φόρτος〉</p></section></article>\n<article id=\"entry-dgp-42994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόρτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 788 na letra φ · nº geral 42994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fardo; carga; carregamento 2 fardo (de males) 3 grosseria; zombaria. 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-42995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορτοφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 789 na letra φ · nº geral 42995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">levar uma carga. 〈φόρτος, φορά〉</p></section></article>\n<article id=\"entry-dgp-42996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 790 na letra φ · nº geral 42996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. pas. ἐφορυνόμην) sujar-se, manchar-se (ao se misturar).</p></section></article>\n<article id=\"entry-dgp-42997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορύσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 791 na letra φ · nº geral 42997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. aor. φορύξας) 1 sujar 2 misturar ♦ méd. 3 sujar-se ♦ pas. 4 estar sujo de, dat. ou gen. 〈φορύνω〉</p></section></article>\n<article id=\"entry-dgp-42998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φορυτός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 792 na letra φ · nº geral 42998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sujeira 2 imundície 3 pocilga 4 palha ou feno (para embalagens de objetos frágeis ou para construir ninhos) 5 mistura de alimentos. 〈φορύνω〉</p></section></article>\n<article id=\"entry-dgp-42999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόως (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 793 na letra φ · nº geral 42999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = φάος.</p></section></article>\n<article id=\"entry-dgp-43000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόωσδε</h1><div class=\"entry-meta\"><span>DGP · ordem 794 na letra φ · nº geral 43000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. à luz do dia. 〈φόως, δε〉</p></section></article>\n";
